#include <WiFi.h>
#include <Wire.h>
#include <DHT.h>
#include <LiquidCrystal_I2C.h>

// --- 1. Cấu hình chân phần cứng ---
#define DHTPIN 14
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);

#define PIR_PIN 13

// Màn hình LCD 1602 I2C (SDA = GPIO 8, SCL = GPIO 18)
LiquidCrystal_I2C lcd(0x27, 16, 2);

// Động cơ Servo Pan-Tilt
#define SERVO_X_PIN 41
#define SERVO_Y_PIN 42

#define CHANNEL_X 0
#define CHANNEL_Y 1

// --- 2. Cấu hình Wi-Fi AP cho Robot ---
const char* ssid = "ESP32-S3-Robot";
const char* password = "12345678";
WiFiServer server(80);

// Hàm điều khiển góc quay Servo (0 - 180 độ)
void setServoAngle(int channel, int angle) {
  int duty = map(angle, 0, 180, 1638, 8192); // Tần số 50Hz, độ phân giải 16-bit
  ledcWrite(channel, duty);
}

void setup() {
  Serial.begin(115200);

  // Khởi tạo cảm biến và ngoại vi
  dht.begin();
  pinMode(PIR_PIN, INPUT);

  // Khởi tạo giao tiếp I2C cho LCD 1602
  Wire.begin(8, 18);
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("AI Robot Ready");

  // Cấu hình PWM chuẩn cho Servo
  ledcSetup(CHANNEL_X, 50, 16);
  ledcAttachPin(SERVO_X_PIN, CHANNEL_X);

  ledcSetup(CHANNEL_Y, 50, 16);
  ledcAttachPin(SERVO_Y_PIN, CHANNEL_Y);

  setServoAngle(CHANNEL_X, 90); // Đưa về giữa
  setServoAngle(CHANNEL_Y, 90);

  // Khởi động phát sóng Wi-Fi nội bộ
  WiFi.softAP(ssid, password);
  server.begin();

  Serial.println("Da khoi dong he thong robot thanh cong!");
}

void loop() {
  // Đọc giá trị nhiệt độ, độ ẩm từ DHT11
  float h = dht.readHumidity();
  float t = dht.readTemperature();

  // Đọc trạng thái cảm biến chuyển động PIR
  int motion = digitalRead(PIR_PIN);

  // Cập nhật thông tin lên màn hình LCD 1602
  lcd.setCursor(0, 1);
  if (!isnan(h) && !isnan(t)) {
    lcd.print("T:"); 
    lcd.print((int)t); 
    lcd.print("C H:"); 
    lcd.print((int)h); 
    lcd.print("% ");
  } else {
    lcd.print("DHT Error     ");
  }

  // Nếu phát hiện chuyển động, kích hoạt cơ chế quét của Servo X
  if (motion == HIGH) {
    lcd.print("Motion!");
    setServoAngle(CHANNEL_X, 45);
    delay(250);
    setServoAngle(CHANNEL_X, 135);
    delay(250);
    setServoAngle(CHANNEL_X, 90);
  } else {
    lcd.print("Safe   ");
  }

  // Xử lý kết nối từ Web Client (Điện thoại kết nối vào Wi-Fi của Robot)
  WiFiClient client = server.available();
  if (client) {
    String request = client.readStringUntil('\n');
    client.println("HTTP/1.1 200 OK");
    client.println("Content-Type: text/html; charset=utf-8");
    client.println("");
    client.println("<!DOCTYPE HTML><html><body>");
    client.println("<h2>ESP32-S3 AI Robot Control Panel</h2>");
    client.println("<p>Nhiệt độ môi trường: " + String(t) + " &deg;C</p>");
    client.println("<p>Độ ẩm không khí: " + String(h) + " %</p>");
    client.println("<p>Trạng thái PIR: " + String(motion ? "Phát hiện chuyển động!" : "An toàn") + "</p>");
    client.println("</body></html>");
    client.stop();
  }

  delay(1000);
}
